def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]
    opp_d = sum(1 for a, b in history if b == 'D')
    my_d = sum(1 for a, b in history if a == 'D')

    recent_opp_d = sum(1 for a, b in history[-5:] if b == 'D')

    opp_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            opp_streak += 1
        else:
            break

    punish_d = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'D':
            punish_d += 1

    if opp_d == 0:
        if n == 49:
            return 'D'
        if n == 50:
            return 'C'
        if n > 50:
            return 'D'

    if n >= 60 and punish_d == 0 and my_d >= 1 and opp_d * 3 <= n and last_opp == 'C':
        return 'D'

    if n >= 8 and opp_d * 2 >= n and opp_d >= 4:
        return 'D'

    if recent_opp_d >= 4:
        return 'D'

    if last_opp == 'D':
        if opp_streak >= 2 and last_my == 'C':
            return 'D'

        provoked = n >= 2 and history[-2][0] == 'D'

        if (last_my == 'D' or provoked) and n >= 6 and opp_d <= max(3, n // 3) and recent_opp_d <= 3:
            return 'C'

        return 'D'

    return 'C'
